// Helper to clean base64 string
const cleanBase64 = (b64: string) => {
    if (!b64) return "";
    return b64.split(',')[1] || b64;
};

// Helper to safely parse JSON that might be wrapped in markdown
const cleanAndParseJSON = (text: string) => {
    if (!text) return {};
    let clean = text.trim();
    if (clean.startsWith('```')) {
        clean = clean.replace(/^```(json)?\n/, '').replace(/\n```$/, '');
    }
    clean = clean.trim();
    try {
        return JSON.parse(clean);
    } catch (e) {
        console.error("JSON Parse Error:", e, "Input text:", text);
        return {};
    }
};

// Helper to wait
const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Retry wrapper
async function retryOperation<T>(operation: () => Promise<T>, retries = 3, backoff = 2000): Promise<T> {
    try {
        return await operation();
    } catch (error: any) {
        const isRetryable = 
            error?.status === 429 || error?.code === 429 || 
            error?.status === 503 || error?.code === 503 ||
            error?.status === 500 || error?.code === 500 ||
            error?.message?.includes('429') || error?.message?.includes('quota') ||
            error?.message?.includes('overloaded');

        if (retries > 0 && isRetryable) {
             console.warn(`API Error (${error.status || error.code}). Retrying in ${backoff}ms...`);
             await wait(backoff);
             return retryOperation(operation, retries - 1, backoff * 2);
        }
        throw error;
    }
}

