  const [magicLoading, setMagicLoading] = useState<string | null>(null);
  const [selectedAesthetic, setSelectedAesthetic] = useState('');
  // We use config.masterPrompt now, so this local state is temporary binding
  const [directorInput, setDirectorInput] = useState('');
  const [isZipping, setIsZipping] = useState(false);

  // Enhancement State
  const [isEnhancingRef, setIsEnhancingRef] = useState(false);

  // Dropdown Selection States (Visual Persistence)
  const [selectedBioPreset, setSelectedBioPreset] = useState('');
  const [selectedPosePreset, setSelectedPosePreset] = useState('');
  const [selectedGlobalPreset, setSelectedGlobalPreset] = useState('');
  const [selectedPersonaId, setSelectedPersonaId] = useState('');

  // New Innovative Features State
  const [personas, setPersonas] = useState<Persona[]>(DEFAULT_PERSONAS);
  const [showWebcam, setShowWebcam] = useState(false);
  const [showLightingMap, setShowLightingMap] = useState(false);

  // Webcam Refs
  const videoRef = useRef<HTMLVideoElement>(null);
  const webcamStreamRef = useRef<MediaStream | null>(null);

  // Suggestion Review State
  const [pendingSuggestion, setPendingSuggestion] = useState<{
      isOpen: boolean;
      field: string;
      value: any;
      label: string;
  }>({ isOpen: false, field: '', value: null, label: '' });

  // --- API Key Check ---
  useEffect(() => {
    const checkKey = async () => {
       if ((window as any).aistudio) {
           try {
             const selected = await (window as any).aistudio.hasSelectedApiKey();
             setHasKey(selected);
           } catch(e) {
             console.error("Key check failed", e);
           }
       } else {
           setHasKey(true);
       }
    };
    checkKey();
  }, []);

  // --- Webcam Logic ---
  useEffect(() => {
      if (showWebcam) {
          navigator.mediaDevices.getUserMedia({ video: true })
            .then(stream => {
                webcamStreamRef.current = stream;
                if (videoRef.current) {
                    videoRef.current.srcObject = stream;
                }
            })
            .catch(err => {
                console.error("Webcam access denied", err);
                setShowWebcam(false);
                alert("Kon geen toegang krijgen tot de webcam.");
            });
      } else {
          if (webcamStreamRef.current) {
              webcamStreamRef.current.getTracks().forEach(track => track.stop());
              webcamStreamRef.current = null;
          }
      }
      return () => {
          if (webcamStreamRef.current) {
              webcamStreamRef.current.getTracks().forEach(track => track.stop());
          }
      };
  }, [showWebcam]);

  const handleConnectKey = async () => {
      if ((window as any).aistudio) {
          try {
              await (window as any).aistudio.openSelectKey();
              setHasKey(true);
          } catch (e) {
              console.error("Select key failed", e);
          }
      }
