  // --- IMAGE ENHANCEMENT LOGIC (SHARPEN + CONTRAST) ---
  const enhanceReferencePhoto = async (base64: string): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = base64;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = img.width;
            canvas.height = img.height;
            const ctx = canvas.getContext('2d');
            if (!ctx) {
                resolve(base64);
                return;
            }

            // 1. Draw Original
            ctx.drawImage(img, 0, 0);

            try {
                // 2. Get Data for Pixel Manipulation
                const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
                const data = imageData.data;
                const w = canvas.width;
                const h = canvas.height;

                // 3. Contrast Boost (Factor 1.2 = 20% boost)
                const contrast = 1.2;
                const intercept = 128 * (1 - contrast);

                // 4. Sharpening Kernel (Simple 3x3)
                // [ 0, -1,  0 ]
                // [-1,  5, -1 ]
                // [ 0, -1,  0 ]
                const mix = 0.5; // Sharpen Strength

                // We create a copy buffer to read from while writing to 'data'
                const buffer = new Uint8ClampedArray(data);

                for (let y = 1; y < h - 1; y++) {
                    for (let x = 1; x < w - 1; x++) {
                        const idx = (y * w + x) * 4;

                        // Apply Contrast
                        for (let c = 0; c < 3; c++) { // RGB
                            let val = buffer[idx + c];
                            // Contrast formula
                            val = val * contrast + intercept;

                            // Sharpening Logic
                            const up = buffer[((y - 1) * w + x) * 4 + c];
                            const down = buffer[((y + 1) * w + x) * 4 + c];
                            const left = buffer[(y * w + (x - 1)) * 4 + c];
                            const right = buffer[(y * w + (x + 1)) * 4 + c];

                            const sharpenVal = (val * 5) - (up + down + left + right);

                            // Blend original with sharpened result
                            data[idx + c] = Math.max(0, Math.min(255, (val * (1 - mix)) + (sharpenVal * mix)));
                        }
                        // Alpha remains same
                    }
                }

                ctx.putImageData(imageData, 0, 0);
                resolve(canvas.toDataURL('image/jpeg', 0.95));
            } catch (e) {
                console.warn("Enhancement failed, using original", e);
                resolve(base64);
            }
        };
        img.onerror = () => resolve(base64);
    });
  };

