             setConfig(prev => {
                const newSubjects = [...prev.subjects];
                const activeSub = newSubjects[activeSubjectIdx];

                // Update World Props if they exist
                const newWorld = { ...prev.world };
                if (script.location) newWorld.location = script.location;
