                const newMasterPrompt = directorInput; 

                // Helper to normalize keys (AI might return TitleCase)
                const normalize = (obj: any) => {
                     const n: any = {};
                     if(!obj) return n;
                     Object.keys(obj).forEach(k => n[k.toLowerCase()] = obj[k]);
                     return n;
                };

                // 1. DUO DIRECTOR MODE: Check for subject1 / subject2 specific outputs
                if (prev.mode === 'duo' && (script.subject1 || script.subject2)) {
                    if (script.subject1 && script.subject1.wardrobe) {
