  // --- UPSCALING & SHARPENING LOGIC ---
  const upscaleImage = async (src: string, resolution: OutputResolution): Promise<string> => {
     return new Promise((resolve) => {
        const img = new Image();
        img.src = src;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            let targetWidth = img.width;
            let targetHeight = img.height;

            if (resolution === OutputResolution.RES_4K) {
                targetWidth = 3840;
                targetHeight = (3840 / img.width) * img.height;
            } else if (resolution === OutputResolution.RES_8K) {
                targetWidth = 7680;
                targetHeight = (7680 / img.width) * img.height;
            }

            canvas.width = targetWidth;
            canvas.height = targetHeight;
            const ctx = canvas.getContext('2d');
            if (ctx) {
                // 1. High Quality Scaling
                ctx.imageSmoothingEnabled = true;
                ctx.imageSmoothingQuality = 'high';
                ctx.drawImage(img, 0, 0, targetWidth, targetHeight);

                // 2. Unsharp Mask (Sharpening Pass) for 4K/8K
                // Note: Only perform if reasonable size to avoid browser crash
                if (resolution !== OutputResolution.RES_2K && targetWidth < 10000) {
                    try {
                        const imageData = ctx.getImageData(0, 0, targetWidth, targetHeight);
                        const pixels = imageData.data;
                        const w = targetWidth;
                        const h = targetHeight;
                        const mix = 0.2; // Sharpening strength (0.0 - 1.0)

                        // Simple kernel-like sharpening approach:
                        // Boost center pixel relative to neighbors
                        // This loop skips edges for simplicity/speed
                        for (let y = 1; y < h - 1; y++) {
                            for (let x = 1; x < w - 1; x++) {
                                const idx = (y * w + x) * 4;
                                // Get neighbors
                                const left = ((y * w + (x - 1)) * 4);
                                const right = ((y * w + (x + 1)) * 4);
                                const up = (((y - 1) * w + x) * 4);
                                const down = (((y + 1) * w + x) * 4);

                                // For RGB channels
                                for (let c = 0; c < 3; c++) {
                                    const val = pixels[idx + c];
                                    const neighborAvg = (pixels[left + c] + pixels[right + c] + pixels[up + c] + pixels[down + c]) * 0.25;
                                    const diff = val - neighborAvg;
                                    // Add difference back to original (Unsharp Mask)
                                    pixels[idx + c] = Math.min(255, Math.max(0, val + (diff * 2.0 * mix)));
                                }
                            }
                        }
                        ctx.putImageData(imageData, 0, 0);
                    } catch (e) {
                        console.warn("Sharpening pass failed (likely CORS or memory), skipping.", e);
                    }
                }

                resolve(canvas.toDataURL('image/png'));
            } else {
                resolve(src);
            }
        };
        img.onerror = () => resolve(src);
     });
  };

