      } else {
         const img = new Image();
         img.src = finalUrl;
         img.onload = () => {
             const canvas = document.createElement('canvas');
             canvas.width = img.width;
             canvas.height = img.height;
             const ctx = canvas.getContext('2d');
             if(ctx) {
                 ctx.fillStyle = '#000';
                 ctx.fillRect(0,0, canvas.width, canvas.height);
                 ctx.drawImage(img, 0, 0);
                 a.href = canvas.toDataURL('image/jpeg', 0.95);
                 a.download = `aura-${asset.id}-web.jpg`;
                 a.click();
             }
         };
      }
  };

  const downloadBundle = async (asset: GeneratedAsset) => {
      if (typeof JSZip === 'undefined') {
          alert("ZIP bibliotheek niet geladen. Refresh de pagina.");
          return;
      }
      setIsZipping(true);
      try {
          const zip = new JSZip();
          const folder = zip.folder(`aura-session-${asset.id}`);

          // Upscale logic
          const upscaledUrl = await upscaleImage(asset.url, asset.config.tech.resolution);

          const rawBlob = base64ToBlob(upscaledUrl, 'image/png');
          folder.file(`aura-${asset.id}-raw.png`, rawBlob);

          await new Promise<void>((resolve) => {
             const img = new Image();
             img.src = upscaledUrl;
             img.onload = () => {
                 const canvas = document.createElement('canvas');
                 canvas.width = img.width;
                 canvas.height = img.height;
                 const ctx = canvas.getContext('2d');
                 if(ctx) {
                     ctx.fillStyle = '#000';
                     ctx.fillRect(0,0, canvas.width, canvas.height);
                     ctx.drawImage(img, 0, 0);
                     const jpgData = canvas.toDataURL('image/jpeg', 0.95);
                     const jpgBlob = base64ToBlob(jpgData, 'image/jpeg');
                     folder.file(`aura-${asset.id}-web.jpg`, jpgBlob);
                     folder.file(`prompt-metadata.txt`, asset.promptUsed);
                     resolve();
                 }
             };
             img.onerror = () => resolve();
          });

          const content = await zip.generateAsync({ type: "blob" });
          const a = document.createElement('a');
          a.href = URL.createObjectURL(content);
          a.download = `aura-bundle-${asset.id}.zip`;
          a.click();
