// --- Single Image Uploader (Enhanced with Download) ---
export const ImageUploader = ({ image, onUpload, label }: { image: string | null, onUpload: (b64: string) => void, label: string }) => {
  const [isProcessing, setIsProcessing] = React.useState(false);

  const handleFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    // ... existing upload logic ...
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    try {
        if (file.name.toLowerCase().endsWith('.heic') || file.type === 'image/heic') {
             if (typeof heic2any !== 'undefined') {
                const convertedBlob = await heic2any({ blob: file, toType: "image/jpeg", quality: 0.9 });
                const blob = Array.isArray(convertedBlob) ? convertedBlob[0] : convertedBlob;
                const reader = new FileReader();
                reader.onloadend = () => { onUpload(reader.result as string); setIsProcessing(false); };
                reader.readAsDataURL(blob);
                e.target.value = '';
                return;
             }
        }
    } catch (err) { console.error("HEIC failed", err); }

    if (file.type.startsWith('video/')) {
      const video = document.createElement('video');
      video.src = URL.createObjectURL(file);
      video.muted = true;
      video.playsInline = true;
      video.crossOrigin = "anonymous";
      video.onloadedmetadata = () => { video.currentTime = Math.min(1.0, video.duration / 2); };
      video.onseeked = () => {
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext('2d');
        if (ctx) { ctx.drawImage(video, 0, 0); onUpload(canvas.toDataURL('image/jpeg', 0.9)); }
        URL.revokeObjectURL(video.src);
        setIsProcessing(false);
      };
      video.onerror = () => { setIsProcessing(false); };
    } else {
      const reader = new FileReader();
      reader.onloadend = () => { onUpload(reader.result as string); setIsProcessing(false); };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  };

  return (
    <div className="mb-6">
       <span className="text-xs font-medium text-gray-400 uppercase tracking-wider block mb-2">{label}</span>
