export const MultiImageUploader = ({ images, onAdd, onRemove, label }: { images: string[], onAdd: (b64: string) => void, onRemove: (index: number) => void, label: string }) => {
  const [isProcessing, setIsProcessing] = React.useState(false);

  const handleFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    // ... existing upload logic ...
    const files = e.target.files;
    if (!files) return;
    setIsProcessing(true);
    let processed = 0;
    const total = files.length;
    const finish = () => { processed++; if (processed === total) setIsProcessing(false); };
    const fileList: File[] = Array.from(files);

    for (const file of fileList) {
      if (file.name.toLowerCase().endsWith('.heic') || file.type === 'image/heic') {
         try {
             if (typeof heic2any !== 'undefined') {
                const convertedBlob = await heic2any({ blob: file, toType: "image/jpeg", quality: 0.9 });
                const blob = Array.isArray(convertedBlob) ? convertedBlob[0] : convertedBlob;
                const reader = new FileReader();
                reader.onloadend = () => { onAdd(reader.result as string); finish(); };
                reader.readAsDataURL(blob);
             } else { finish(); }
         } catch (err) { finish(); }
      } else if (file.type.startsWith('video/')) {
        const video = document.createElement('video');
        video.src = URL.createObjectURL(file);
        video.muted = true;
        video.playsInline = true;
        video.crossOrigin = "anonymous";
        video.onloadedmetadata = () => { video.currentTime = Math.min(1.0, video.duration / 2); };
        video.onseeked = () => {
          const canvas = document.createElement('canvas');
          canvas.width = video.videoWidth;
          canvas.height = video.videoHeight;
          const ctx = canvas.getContext('2d');
          if (ctx) { ctx.drawImage(video, 0, 0); onAdd(canvas.toDataURL('image/jpeg', 0.9)); }
          URL.revokeObjectURL(video.src);
          finish();
        };
        video.onerror = () => finish();
      } else {
        const reader = new FileReader();
        reader.onloadend = () => { onAdd(reader.result as string); finish(); };
        reader.readAsDataURL(file);
      }
    }
    e.target.value = '';
  };

  return (
    <div className="mb-6 group">
       <div className="flex justify-between items-center mb-2">
         <span className="text-xs font-medium text-gray-400 uppercase tracking-wider">{label}</span>
         <span className="text-[10px] text-gray-500">{images.length}/5 Assets</span>
       </div>
       <div className="grid grid-cols-3 gap-2">
         {images.map((img, idx) => (
           <div key={idx} className="relative aspect-square rounded-lg overflow-hidden border border-white/10 group/item transition-all hover:border-aura-accent">
