             <div className="absolute top-1 right-1 flex gap-1 opacity-0 group-hover/item:opacity-100 transition-opacity">
                 {/* DOWNLOAD BUTTON */}
                 <button 
                   onClick={() => downloadBase64(img, `aura-subject-ref-${idx}.jpg`)}
                   className="bg-black/50 hover:bg-aura-accent text-white rounded-full p-1 transition-colors backdrop-blur-sm"
                   title="Download"
                 >
                   <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                 </button>
                 {/* REMOVE BUTTON */}
                 <button 
