  DEFAULT_STATE,
  LOCATIONS, LIGHTING_PRESETS, CAMERA_TYPES, CAMERA_BRANDS, FOCAL_LENGTHS,
  PRESETS
} from './constants';
import { auraEngine } from './services/geminiService';
import { 
  AuraLoader, LuxuryButton, LuxuryInput, LuxurySlider, 
  LuxurySelect, LuxuryDropdown, GlassCard, ImageUploader, 
  MultiImageUploader, Collapsible, ReviewModal
} from './components/UIComponents';

export default function App() {
  const [appMode, setAppMode] = useState<AppMode>(AppMode.STUDIO);
  const [state, setState] = useState<AuraState>(DEFAULT_STATE);
  const [isGenerating, setIsGenerating] = useState(false);
  const [loaderText, setLoaderText] = useState<{title: string, subtitle?: string} | null>(null);
  const [gallery, setGallery] = useState<GeneratedAsset[]>([]);
  const [directorInput, setDirectorInput] = useState('');

  const [suggestion, setSuggestion] = useState<{ isOpen: boolean; title: string; content: any; onAccept: () => void; }>({ isOpen: false, title: '', content: '', onAccept: () => {} });

  useEffect(() => { setDirectorInput(state.masterPrompt); }, [state.masterPrompt]);

  const updateState = (fn: (prev: AuraState) => AuraState) => setState(prev => fn(prev));
  const updateSubject = (index: number, updates: any) => updateState(prev => {
      const newSubs = [...prev.subjects];
      newSubs[index] = { ...newSubs[index], ...updates };
      return { ...prev, subjects: newSubs };
  });
  const updateBio = (idx: number, u: any) => updateSubject(idx, { bio: { ...state.subjects[idx].bio, ...u } });
  const updateWardrobe = (idx: number, u: any) => updateSubject(idx, { wardrobe: { ...state.subjects[idx].wardrobe, ...u } });

  const handleGenerate = async () => {
    setIsGenerating(true);
    const count = state.tech.numberOfImages || 1;

    try {
        for (let i = 0; i < count; i++) {
            setLoaderText({ title: `Rendering Image ${i+1}/${count}`, subtitle: "Calculating Rays..." });
            const prompt = await auraEngine.compilePrompt({ ...state, masterPrompt: directorInput });
            const url = await auraEngine.generateImage({ ...state, masterPrompt: directorInput }, prompt);
            const asset: GeneratedAsset = { id: Date.now().toString() + i, url, timestamp: Date.now(), config: state, promptUsed: prompt };
            setGallery(prev => [asset, ...prev]);

            if (state.tech.autoDownload) {
                const link = document.createElement("a"); 
                link.href = url; 
                link.download = `aura-auto-${asset.id}.png`; 
                document.body.appendChild(link); 
                link.click(); 
                document.body.removeChild(link);
            }
        }
        setAppMode(AppMode.GALLERY);
    } catch (e: any) { alert(e.message); } 
    finally { setIsGenerating(false); setLoaderText(null); }
  };

  const handleDirector = async () => {
      setLoaderText({ title: "AI Director", subtitle: state.tech.directorModel === TextModelVersion.PRO ? "Thinking Deeply (Gemini 3)..." : "Drafting Script..." });
      const script = await auraEngine.generateSceneScript(directorInput, "", "", state.tech.directorModel);
      setLoaderText(null);
      if (script) {
          setSuggestion({
              isOpen: true, title: "Director's Script", content: script,
              onAccept: () => {
                  updateState(prev => {
                      const newState = { ...prev, masterPrompt: directorInput };
                      if (script.location) newState.world.location = script.location;
                      if (script.lighting) newState.world.lighting = script.lighting;
                      if (script.camera) newState.world.camera = script.camera;

                      const applyW = (subIdx: number, wData: any) => {
                          if (!wData) return;
                          const norm: any = {}; Object.keys(wData).forEach(k => norm[k.toLowerCase()] = wData[k]);
                          newState.subjects[subIdx].wardrobe.items = { ...newState.subjects[subIdx].wardrobe.items, ...norm };
                      };
                      if (newState.mode === 'solo') {
                          applyW(0, script.wardrobe || script.subject1?.wardrobe);
                          if(script.pose) newState.subjects[0].pose = script.pose;
                      } else {
                          applyW(0, script.subject1?.wardrobe);
                          applyW(1, script.subject2?.wardrobe);
                          if(script.subject1?.pose) newState.subjects[0].pose = script.subject1.pose;
                          if(script.subject2?.pose) newState.subjects[1].pose = script.subject2.pose;
                      }
                      return newState;
                  });
                  setSuggestion(prev => ({...prev, isOpen: false}));
              }
          });
      }
  };

  const renderSubject = (i: number) => {
      const s = state.subjects[i];
      return (
          <div className="space-y-4">
              <GlassCard className="p-4">
                  <h3 className="text-white font-bold mb-2">01. Identity</h3>
