                      <LuxurySelect label="Gender" value={s.gender} options={['female','male','non-binary']} onChange={(v:any)=>updateSubject(i, {gender:v})} />
                      <LuxurySlider label="Age" value={s.bio.age} onChange={(v:any)=>updateBio(i, {age:v})} min={18} max={90} />
                      <LuxurySlider label="Height (cm)" value={s.bio.height} onChange={(v:any)=>updateBio(i, {height:v})} min={140} max={220} />
                      <LuxurySelect label="Body Shape" value={s.bio.bodyShape} options={['hourglass','pear','athletic','rectangle']} onChange={(v:any)=>updateBio(i, {bodyShape:v})} />
                      <LuxurySlider label="Bust" value={s.bio.bustSize} onChange={(v:any)=>updateBio(i, {bustSize:v})} />
                      <LuxurySlider label="Waist" value={s.bio.waist} onChange={(v:any)=>updateBio(i, {waist:v})} />
                      <LuxurySlider label="Hips/Butt" value={s.bio.buttSize} onChange={(v:any)=>updateBio(i, {buttSize:v})} />
                  </Collapsible>
                  <Collapsible title="References">
                      <MultiImageUploader label="Face Refs" images={s.baseImages} onAdd={(b:string)=>updateSubject(i, {baseImages:[...s.baseImages, b]})} onRemove={(idx:number)=>updateSubject(i, {baseImages:s.baseImages.filter((_,x)=>x!==idx)})} />
                  </Collapsible>
              </GlassCard>
              <GlassCard className="p-4">
                  <div className="mb-4">
                    <h3 className="text-white font-bold">02. Action & Pose</h3>
                    <LuxuryInput label="Global Director Prompt" value={directorInput} onChange={setDirectorInput} area placeholder="Describe the scene..." />
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-[10px] text-gray-400">Director Brain:</span>
                        <button onClick={()=>updateState(p=>({...p, tech: {...p.tech, directorModel: p.tech.directorModel === TextModelVersion.FLASH ? TextModelVersion.PRO : TextModelVersion.FLASH}}))} className={`text-[10px] px-2 rounded ${state.tech.directorModel === TextModelVersion.PRO ? 'bg-aura-accent text-white' : 'bg-gray-700 text-gray-300'}`}>{state.tech.directorModel === TextModelVersion.PRO ? 'PRO (Smart)' : 'FLASH (Fast)'}</button>
                    </div>
                    <LuxuryButton onClick={handleDirector} variant="secondary" className="w-full">🎬 Generate Script</LuxuryButton>
                  </div>
                  <LuxuryInput label="Pose Description" value={s.pose} onChange={(v:string)=>updateSubject(i, {pose:v})} area onToggleLock={()=>updateSubject(i, {poseLocked:!s.poseLocked})} isLocked={s.poseLocked} />
                  <ImageUploader label="Pose Reference" image={s.poseReferenceImage} onUpload={(b:string)=>updateSubject(i, {poseReferenceImage:b})} />
              </GlassCard>
              <GlassCard className="p-4">
                  <h3 className="text-white font-bold mb-2">03. Wardrobe</h3>
                  <Collapsible title="Garments">
                      {['underwear','legwear','top','bottom','shoes','accessories','headwear'].map(key => (
                          <LuxuryInput key={key} label={key} value={(s.wardrobe.items as any)[key]} onChange={(v:string)=>updateWardrobe(i, {items:{...s.wardrobe.items, [key]:v}})} />
