## services/geminiService.ts

Full implementation with Anti-Collage and strict JSON parsing.

```typescript
import { GoogleGenAI } from "@google/genai";
import { AuraState } from "../types";
import { MASTER_PROMPT_BIBLE } from "../constants";

const cleanBase64 = (b64: string) => b64.split(',')[1] || b64;
const parseJSON = (text: string) => { 
    try { return JSON.parse(text.replace(/```json|```/g, '').trim()); } 
    catch (e) { return {}; } 
};

export class AuraEngine {
  private getClient() { return new GoogleGenAI({ apiKey: process.env.API_KEY || '' }); }

  async generateSceneScript(concept: string, locked: string, ctx: string, model: string) {
      const client = this.getClient();
      const prompt = `Director Mode. Concept: "${concept}". ${ctx} ${locked}. OUTPUT JSON: location, lighting, camera, subject1: { wardrobe: { headwear, underwear, legwear, top, bottom, shoes, accessories }, pose }, subject2: { ... }. DUTCH.`;
      const res = await client.models.generateContent({ model, contents: prompt, config: { responseMimeType: 'application/json' } });
      return parseJSON(res.text || "{}");
  }

  async generateDuoLook(img: string, ctx: any) {
      const client = this.getClient();
      const prompt = `Analyze Couple. Context: ${JSON.stringify(ctx)}. JSON Output: subject1: { gender, wardrobe }, subject2: { gender, wardrobe }. Dutch.`;
      const res = await client.models.generateContent({ model: 'gemini-2.5-flash', contents: { parts: [{text: prompt}, {inlineData: {mimeType: 'image/jpeg', data: cleanBase64(img)}}] }, config: { responseMimeType: 'application/json' } });
      return parseJSON(res.text || "{}");
  }

  async analyzeGarment(img: string) { return this.generateDuoLook(img, { task: "analyze_single_garment" }); } // Simplified reuse
  async analyzePose(img: string) { 
      const client = this.getClient();
      const res = await client.models.generateContent({ model: 'gemini-2.5-flash', contents: { parts: [{text: "Analyze SKELETAL POSE ONLY. Dutch."}, {inlineData: {mimeType: 'image/jpeg', data: cleanBase64(img)}}] } });
      return res.text || "";
  }

  async compilePrompt(state: AuraState): Promise<string> {
      const subPrompts = state.subjects.map((s, i) => `SUBJECT ${i+1} (${s.gender}): ${s.bio.bodyShape}, ${s.bio.height}cm. Pose: ${s.pose}. Wardrobe: ${JSON.stringify(s.wardrobe.items)}.`).join('\n');
      const tech = `Camera: ${state.world.cameraBrand} ${state.world.camera} ${state.world.focalLength}. Bokeh: ${state.world.bokehAmount}. Chaos: ${state.world.chaosLevel}.`;
      return `${MASTER_PROMPT_BIBLE}\n\nMASTER: ${state.masterPrompt}\nSCENE: ${state.world.location}, ${state.world.lighting}.\n${tech}\n${subPrompts}\nNEGATIVE: ${state.world.negativePrompt}`;
  }

  async generateImage(state: AuraState, prompt: string): Promise<string> {
      const parts: any[] = [{ text: prompt + " NEGATIVE: collage, composite, split screen." }];
      if (state.mode === 'duo' && state.coupleReferenceImage) parts.push({ inlineData: { mimeType: 'image/jpeg', data: cleanBase64(state.coupleReferenceImage) } });
      state.subjects.forEach((s, i) => {
          s.baseImages.forEach(img => parts.push({ inlineData: { mimeType: 'image/jpeg', data: cleanBase64(img) } }));
          if (s.poseReferenceImage) parts.push({ inlineData: { mimeType: 'image/jpeg', data: cleanBase64(s.poseReferenceImage) } });
      });
      const client = this.getClient();
      const res = await client.models.generateContent({ model: 'gemini-3-pro-image-preview', contents: { parts }, config: { imageConfig: { aspectRatio: state.tech.aspectRatio as any, imageSize: '2K' } } });
      return `data:image/png;base64,${res.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || ''}`;
  }
}
export const auraEngine = new AuraEngine();
```

