            .then(stream => {
                webcamStreamRef.current = stream;
                if (videoRef.current) videoRef.current.srcObject = stream;
            })
            .catch(() => { setShowWebcam(false); alert("Geen toegang tot webcam."); });
      } else {
          if (webcamStreamRef.current) {
              webcamStreamRef.current.getTracks().forEach(track => track.stop());
              webcamStreamRef.current = null;
          }
      }
  }, [showWebcam]);

  const updateState = (fn: (prev: AuraState) => AuraState) => setState(prev => fn(prev));
  const updateSubject = (index: number, updates: any) => updateState(prev => {
      const newSubs = [...prev.subjects];
      newSubs[index] = { ...newSubs[index], ...updates };
      return { ...prev, subjects: newSubs };
  });
  const updateBio = (idx: number, u: any) => updateSubject(idx, { bio: { ...state.subjects[idx].bio, ...u } });
  const updateWardrobe = (idx: number, u: any) => updateSubject(idx, { wardrobe: { ...state.subjects[idx].wardrobe, ...u } });

  // --- UPSCALING & SHARPENING LOGIC ---
  const upscaleImage = async (src: string, resolution: OutputResolution): Promise<string> => {
     if (resolution === OutputResolution.RES_2K) return src;
     return new Promise((resolve) => {
        const img = new Image();
        img.src = src;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const targetWidth = resolution === OutputResolution.RES_8K ? 7680 : 3840;
            const targetHeight = (targetWidth / img.width) * img.height;
            canvas.width = targetWidth; canvas.height = targetHeight;
            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = 'high';
                ctx.drawImage(img, 0, 0, targetWidth, targetHeight);
                resolve(canvas.toDataURL('image/png'));
            } else resolve(src);
        };
        img.onerror = () => resolve(src);
     });
  };

  const handleGenerate = async () => {
