```typescript
import React, { useState, useEffect, useRef } from 'react';
import { AppMode, AuraState, GeneratedAsset, OutputResolution, TextModelVersion, SubjectConfig, Persona } from './types';
import { DEFAULT_STATE, LOCATIONS, LIGHTING_PRESETS, CAMERA_TYPES, CAMERA_BRANDS, FOCAL_LENGTHS, PRESETS, DEFAULT_PERSONAS, LENS_DESCRIPTIONS, CAMERA_DESCRIPTIONS, BIO_PRESETS, SELFIE_MODES, BODY_SHAPES, FIT_OPTIONS, AESTHETICS } from './constants';
import { auraEngine } from './services/geminiService';
import { AuraLoader, LuxuryButton, LuxuryInput, LuxurySlider, LuxurySelect, LuxuryDropdown, GlassCard, ImageUploader, MultiImageUploader, Collapsible, ReviewModal, InfoTooltip } from './components/UIComponents';

export default function App() {
  const [state, setState] = useState<AuraState>(DEFAULT_STATE);
  const [appMode, setAppMode] = useState<AppMode>(AppMode.STUDIO);
  const [gallery, setGallery] = useState<GeneratedAsset[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [loadingText, setLoadingText] = useState("");
  const [suggestion, setSuggestion] = useState<any>({ isOpen: false });
  const [personas, setPersonas] = useState<Persona[]>(DEFAULT_PERSONAS);
  const [showWebcam, setShowWebcam] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);

  useEffect(() => { console.log("Aura Studio Loaded"); }, []);
  useEffect(() => { 
      if(showWebcam && videoRef.current) navigator.mediaDevices.getUserMedia({video:true}).then(s=>videoRef.current!.srcObject=s).catch(e=>console.error(e)); 
  }, [showWebcam]);

  const updateState = (fn: any) => setState(prev => fn(prev));
  const updateSubject = (i: number, u: any) => updateState((p:any) => { const s=[...p.subjects]; s[i]={...s[i],...u}; return {...p, subjects:s}; });
  const updateBio = (i: number, u: any) => updateSubject(i, { bio: { ...state.subjects[i].bio, ...u } });
  const updateWardrobe = (i: number, u: any) => updateSubject(i, { wardrobe: { ...state.subjects[i].wardrobe, ...u } });

  const upscaleImage = async (src: string, res: OutputResolution) => {
      if(res === OutputResolution.RES_2K) return src;
      return new Promise<string>(resolve => {
          const img = new Image(); img.src = src;
          img.onload = () => {
              const cvs = document.createElement('canvas'); const ctx = cvs.getContext('2d');
              const w = res === OutputResolution.RES_8K ? 7680 : 3840;
              const h = (w/img.width) * img.height;
              cvs.width = w; cvs.height = h;
              ctx?.drawImage(img, 0, 0, w, h);
              resolve(cvs.toDataURL('image/png'));
          };
          img.onerror = () => resolve(src);
      });
  };

  const handleGenerate = async () => {
      setIsGenerating(true);
      try {
          const count = state.tech.numberOfImages || 1;
          for(let i=0; i<count; i++) {
              setLoadingText(`Rendering ${i+1}/${count}...`);
              const prompt = await auraEngine.compilePrompt(state);
              const rawUrl = await auraEngine.generateImage(state, prompt);
              const finalUrl = await upscaleImage(rawUrl, state.tech.resolution);
              const asset = { id: Date.now()+""+i, url: finalUrl, timestamp: Date.now(), config: state, promptUsed: prompt };
              setGallery(p => [asset, ...p]);
              if(state.tech.autoDownload) { const a = document.createElement('a'); a.href=finalUrl; a.download=`aura-${asset.id}.png`; a.click(); }
          }
          setAppMode(AppMode.GALLERY);
      } catch(e:any) { alert(e.message); } finally { setIsGenerating(false); setLoadingText(""); }
  };

  const handleDirector = async () => {
      setLoadingText("Director is thinking...");
      const script = await auraEngine.generateSceneScript(state.masterPrompt, "", "", state.tech.directorModel);
      setLoadingText("");
      if(script) setSuggestion({ isOpen: true, title: "Director Script", content: script, onAccept: () => {
          updateState((p:any) => {
              const ns = {...p};
              if(script.location) ns.world.location = script.location;
              if(script.lighting) ns.world.lighting = script.lighting;
              // Add basic Wardrobe mapping
              if(ns.mode==='solo') {
                  const w = script.wardrobe || script.subject1?.wardrobe;
                  if(w) ns.subjects[0].wardrobe.items = {...ns.subjects[0].wardrobe.items, ...w};
                  if(script.pose) ns.subjects[0].pose = script.pose;
              }
              return ns;
          });
          setSuggestion({isOpen:false});
      }});
  };

  const handleDuoStylist = async () => {
      if (!state.coupleReferenceImage) { alert("Upload eerst een Koppel Referentie in 01. Identiteit"); return; }
      setLoadingText("Styling Duo...");
      const script = await auraEngine.generateDuoLook(state.coupleReferenceImage, { location: state.world.location, aesthetic: "Matching" });
      setLoadingText("");
      if (script) {
          setSuggestion({
              isOpen: true, title: "Duo Proposal", content: script,
              onAccept: () => {
                  updateState((p:any) => {
                      const ns = {...p};
                      if(script.subject1?.wardrobe) ns.subjects[0].wardrobe.items = {...ns.subjects[0].wardrobe.items, ...script.subject1.wardrobe};
                      if(script.subject2?.wardrobe) ns.subjects[1].wardrobe.items = {...ns.subjects[1].wardrobe.items, ...script.subject2.wardrobe};
                      return ns;
                  });
                  setSuggestion({isOpen:false});
              }
          })
      }
  };

  const handlePoseUpload = async (b64: string) => {
      updateSubject(0, { poseReferenceImage: b64 });
      if(state.subjects[0].poseLocked) return;
      setLoadingText("Scanning Pose...");
      const desc = await auraEngine.analyzePose(b64);
      setLoadingText("");
      if(desc) setSuggestion({isOpen:true, title:"Pose Analysis", content: desc, onAccept: () => { updateSubject(0, {pose: desc}); setSuggestion({isOpen:false}); }});
  };

  const saveSession = () => localStorage.setItem('aura', JSON.stringify({...state, subjects: state.subjects.map(s=>({...s, baseImages:[]}))}));
  const loadSession = () => { const s = localStorage.getItem('aura'); if(s) setState(JSON.parse(s)); };

  const renderStudio = () => (
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
          <div className="space-y-4">
              <GlassCard className="p-4">
                  <h3 className="text-white font-bold mb-2">01. Identity</h3>
                  <div className="flex gap-2 mb-2"><button onClick={()=>updateState((p:any)=>({...p, mode:'solo'}))} className={`flex-1 text-xs py-1 rounded ${state.mode==='solo'?'bg-purple-600':'bg-white/10'}`}>SOLO</button><button onClick={()=>updateState((p:any)=>({...p, mode:'duo'}))} className={`flex-1 text-xs py-1 rounded ${state.mode==='duo'?'bg-purple-600':'bg-white/10'}`}>DUO</button></div>
                  <div className="flex justify-between mb-2"><button onClick={saveSession} className="text-[10px] bg-white/10 px-2">Save Sess.</button><button onClick={loadSession} className="text-[10px] bg-white/10 px-2">Load Sess.</button></div>
                  {state.subjects.map((s, i) => (state.mode==='solo' && i>0 ? null :
                  <Collapsible key={i} title={s.name}>
                      <LuxurySelect label="Gender" value={s.gender} options={['female','male']} onChange={(v:any)=>updateSubject(i,{gender:v})} />
                      <LuxurySlider label="Age" value={s.bio.age} onChange={(v:any)=>updateBio(i,{age:v})} min={18} max={90} />
                      <LuxurySelect label="Body" value={s.bio.bodyShape} options={Object.keys(BODY_SHAPES)} onChange={(v:any)=>updateBio(i,{bodyShape:v})} />
                      <MultiImageUploader label="Face Refs" images={s.baseImages} onAdd={(b:string)=>updateSubject(i,{baseImages:[...s.baseImages,b]})} onRemove={(x:number)=>updateSubject(i,{baseImages:s.baseImages.filter((_,y)=>x!==y)})} />
                  </Collapsible>))}
                  {state.mode === 'duo' && <ImageUploader label="Couple Ref" image={state.coupleReferenceImage} onUpload={(b:string)=>updateState((p:any)=>({...p, coupleReferenceImage:b}))} />}
              </GlassCard>
              <GlassCard className="p-4">
                  <h3 className="text-white font-bold mb-2">02. Pose & Action</h3>
                  <LuxuryInput label="Director Prompt" area value={state.masterPrompt} onChange={(v:string)=>updateState((p:any)=>({...p, masterPrompt:v}))} />
                  <LuxuryButton onClick={handleDirector} className="w-full mb-4">🎬 Generate Script</LuxuryButton>
                  <div className="flex justify-end mb-2"><button onClick={()=>setShowWebcam(!showWebcam)} className="text-[10px] bg-red-900 px-2 rounded">Webcam</button></div>
                  {showWebcam && <video ref={videoRef} autoPlay muted className="w-full rounded mb-2" />}
                  {state.subjects.map((s, i) => (state.mode==='solo' && i>0 ? null :
                  <div key={i} className="mb-2">
                      <LuxuryInput label={`${s.name} Pose`} area value={s.pose} onChange={(v:string)=>updateSubject(i,{pose:v})} />
                      <ImageUploader label="Pose Ref" image={s.poseReferenceImage} onUpload={handlePoseUpload} />
                  </div>))}
              </GlassCard>
          </div>
          <div className="space-y-4">
              <GlassCard className="p-4">
                  <h3 className="text-white font-bold mb-2">03. Wardrobe</h3>
                  {state.mode === 'duo' && state.coupleReferenceImage && <LuxuryButton onClick={handleDuoStylist} className="w-full mb-4 text-xs">✨ Duo Stylist (Ref)</LuxuryButton>}
                  {state.subjects.map((s, i) => (state.mode==='solo' && i>0 ? null :
                  <Collapsible key={i} title={s.name}>
                      <LuxurySelect label="Fit" value={s.wardrobe.fitPreference} options={FIT_OPTIONS} onChange={(v:any)=>updateWardrobe(i,{fitPreference:v})} />
                      {['top','bottom','shoes','underwear'].map(k => <LuxuryInput key={k} label={k} value={(s.wardrobe.items as any)[k]} onChange={(v:string)=>updateWardrobe(i,{items:{...s.wardrobe.items,[k]:v}})} />)}
                  </Collapsible>))}
              </GlassCard>
          </div>
          <div className="space-y-4">
              <GlassCard className="p-4">
                  <h3 className="text-white font-bold mb-2">04. World</h3>
                  <LuxuryInput label="Location" value={state.world.location} onChange={(v:string)=>updateState((p:any)=>({...p, world:{...p.world, location:v}}))} />
                  <LuxurySelect label="Camera" value={state.world.camera} options={CAMERA_TYPES} onChange={(v:any)=>updateState((p:any)=>({...p, world:{...p.world, camera:v}}))} />
                  <LuxurySlider label="Batch Size" value={state.tech.numberOfImages} min={1} max={4} onChange={(v:any)=>updateState((p:any)=>({...p, tech:{...p.tech, numberOfImages:v}}))} />
                  <LuxuryButton onClick={()=>updateState((p:any)=>({...p, tech:{...p.tech, autoDownload:!p.tech.autoDownload}}))} variant="sec" className="w-full text-[10px]">Auto-Download: {state.tech.autoDownload?'ON':'OFF'}</LuxuryButton>
              </GlassCard>
          </div>
      </div>
  );

  return (
      <div className="min-h-screen p-4 pb-24 text-gray-200 font-sans">
          {isGenerating && <AuraLoader text={loadingText} />}
          <ReviewModal isOpen={suggestion.isOpen} title={suggestion.title} content={suggestion.content} onAccept={suggestion.onAccept} onReject={()=>setSuggestion({isOpen:false})} />
          <nav className="flex justify-between mb-4 bg-white/5 p-4 rounded-xl">
              <h1 className="font-bold text-white tracking-widest">AURA <span className="text-purple-500">ULTRA</span></h1>
