  const updateWardrobe = (i: number, u: any) => updateSubject(i, { wardrobe: { ...state.subjects[i].wardrobe, ...u } });

  const upscaleImage = async (src: string, res: OutputResolution) => {
      if(res === OutputResolution.RES_2K) return src;
      return new Promise<string>(resolve => {
          const img = new Image(); img.src = src;
          img.onload = () => {
              const cvs = document.createElement('canvas'); const ctx = cvs.getContext('2d');
              const w = res === OutputResolution.RES_8K ? 7680 : 3840;
              const h = (w/img.width) * img.height;
              cvs.width = w; cvs.height = h;
              ctx?.drawImage(img, 0, 0, w, h);
              resolve(cvs.toDataURL('image/png'));
          };
          img.onerror = () => resolve(src);
      });
  };

