              const prompt = await auraEngine.compilePrompt(state);
              const rawUrl = await auraEngine.generateImage(state, prompt);
              const finalUrl = await upscaleImage(rawUrl, state.tech.resolution);
              const asset = { id: Date.now()+""+i, url: finalUrl, timestamp: Date.now(), config: state, promptUsed: prompt };
              setGallery(p => [asset, ...p]);
              if(state.tech.autoDownload) { const a = document.createElement('a'); a.href=finalUrl; a.download=`aura-${asset.id}.png`; a.click(); }
