  const renderStudio = () => {
      return (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="space-y-4">
              <GlassCard className="p-4">
                  <h3 className="text-white font-bold mb-2">01. Identity</h3>
                  <div className="flex gap-2 mb-2"><button onClick={()=>updateState((p:any)=>({...p, mode:'solo'}))} className={`flex-1 text-xs py-1 rounded ${state.mode==='solo'?'bg-purple-600':'bg-white/10'}`}>SOLO</button><button onClick={()=>updateState((p:any)=>({...p, mode:'duo'}))} className={`flex-1 text-xs py-1 rounded ${state.mode==='duo'?'bg-purple-600':'bg-white/10'}`}>DUO</button></div>
                  <div className="flex justify-between mb-2"><button onClick={saveSession} className="text-[10px] bg-white/10 px-2">Save Sess.</button><button onClick={loadSession} className="text-[10px] bg-white/10 px-2">Load Sess.</button></div>
                  {state.subjects.map((s, i) => (state.mode==='solo' && i>0 ? null :
                  <Collapsible key={i} title={s.name}>
